/**
 * set sets the console variable name to value through serverCommand, which
 * may set a development-only or cheat-protected variable. It returns false
 * when the host refuses.
 */
export function set<Name extends keyof Variables>(
  name: Name,
  value: Variables[Name],
): boolean {
  return serverCommand(`${name} ${format(value)}`)
}

/** format returns value as the console reads it: a boolean as 1 or 0 and text in quotes. */
function format(value: boolean | number | string): string {
  if (typeof value === 'boolean') {
    return value ? '1' : '0'
  }
  return typeof value === 'string' ? `"${value}"` : String(value)
}

/** run runs the console command name with args, each one word of the line. */
export function run(name: keyof Commands, ...args: string[]): boolean {
  return serverCommand([name, ...args].join(' '))
}

